import {
  createGame,
  draw,
  fromBoard,
  hash,
  move,
  observe,
  snapshotPool,
} from "./engine";
import { focusApplies } from "./curriculum";
import { mergeLessons } from "./skills";
import { mapConcurrent } from "./concurrency";
import type {
  Arm,
  ExamRow,
  Lesson,
  Policy,
  RecentMove,
  Verification,
  Workspace,
  Game,
} from "./types";
// Development seeds: used by the UI and for tuning. They are in source control, so they are
// not sealed. Final exams load seeds generated by scripts/seal-seeds.ts (see PROTOCOL.md).
// The hash label is historical; the first six match the v0.1 fixtures.
export const DEV_SEEDS = Array.from({ length: 60 }, (_, i) =>
  hash(`sealed-exam-v1:${i}`),
);
export function parseSealedSeeds(value: unknown): number[] {
  const seeds = (value as { seeds?: unknown })?.seeds;
  if (
    !Array.isArray(seeds) ||
    !seeds.length ||
    seeds.some((s) => !Number.isSafeInteger(s) || s < 0 || s > 0xffffffff) ||
    new Set(seeds).size !== seeds.length
  )
    throw new Error("Sealed seed file must contain unique uint32 seeds.");
  if (seeds.some((s) => DEV_SEEDS.includes(s)))
    throw new Error("Sealed seeds overlap development seeds.");
  return seeds as number[];
}
export const DEFAULT_MOVE_CAP = 1500;
export interface VerifyOptions {
  practice: number;
  regression: number;
  moves: number;
}
export const DEFAULT_VERIFY: VerifyOptions = {
  practice: 6,
  regression: 3,
  moves: 8,
};
export const verificationRule = (o: VerifyOptions) =>
  `Mean practice utility improves by ≥ 1; mean regression utility declines by no more than 2. Utility = rollout score gain / 8 + surviving moves + 2 × final empty cells. ${o.practice} targeted practice and ${o.regression} general regression snapshots; ${o.moves} moves each.`;
export const VERIFICATION_RULE = verificationRule(DEFAULT_VERIFY);
// Agent-level failures (no legal move within the call budget) end an episode; API,
// budget and stop errors abort the operation. This rule is fixed before evaluation.
export const isAgentError = (e: unknown) =>
  e instanceof Error && /^Agent /.test(e.message);
export const pushRecent = (
  recent: RecentMove[],
  move: RecentMove,
): RecentMove[] => [...recent, move].slice(-3);
export async function rollout(
  policy: Policy,
  workspace: Workspace,
  board: number[],
  seed: number,
  cap = 8,
  onUsage?: (tokens: number, calls: number, simulations: number) => void,
  onMove?: (game: Game) => void,
) {
  let game = fromBoard(board, seed);
  let tokens = 0,
    calls = 0,
    simulations = 0,
    errors = 0,
    cited = 0;
  let recent: RecentMove[] = [];
  for (let i = 0; i < cap && !game.over; i++) {
    let d;
    try {
      d = await policy.decide(
        observe(game),
        workspace,
        hash(`verify-plan:${seed}:${i}`),
        { recent },
      );
    } catch (e) {
      if (!isAgentError(e)) throw e;
      errors++;
      break;
    }
    tokens += d.tokens;
    calls += d.calls;
    simulations += d.simulations;
    if (d.lessonId) cited++;
    onUsage?.(d.tokens, d.calls, d.simulations);
    const next = move(game, d.action);
    if (!next.changed) throw new Error("Policy chose an illegal move.");
    recent = pushRecent(recent, {
      action: d.action,
      scoreDelta: next.gain,
      emptyBefore: observe(game).empty,
      emptyAfter: observe(next.game).empty,
    });
    game = next.game;
    onMove?.(game);
  }
  return {
    utility: game.score / 8 + game.moves + observe(game).empty * 2,
    tokens,
    calls,
    simulations,
    errors,
    cited,
  };
}
export async function verifyCandidate(
  policy: Policy,
  current: Workspace,
  lesson: Lesson,
  round: number,
  onUsage?: (tokens: number, calls: number, simulations: number) => void,
  onProgress?: (done: number, total: number) => void,
  options: VerifyOptions = DEFAULT_VERIFY,
  concurrency = 1,
): Promise<Verification> {
  const candidate: Workspace = {
    version: current.version + 1,
    skill: lesson.skill,
    lessons: mergeLessons(current.lessons, {
      ...lesson,
      status: "verified" as const,
    }),
  };
  const focus = lesson.focus;
  const pools = {
    // Practice snapshots exercise the lesson's focus; regression stays general.
    practice: snapshotPool(
      "practice",
      round,
      focus
        ? { key: focus, applies: (b) => focusApplies(focus, b) }
        : undefined,
      options.practice,
    ),
    regression: snapshotPool(
      "regression",
      round,
      undefined,
      options.regression,
    ),
  };
  const total = options.practice + options.regression;
  const snapshots = (["practice", "regression"] as const).flatMap((split) =>
    pools[split].map((snapshot) => ({ split, snapshot })),
  );
  const jobs = snapshots.flatMap(({ snapshot }, pair) =>
    [current, candidate].map((workspace) => ({ snapshot, pair, workspace })),
  );
  const finished = new Array<number>(total).fill(0);
  let pairsDone = 0;
  // Each rollout has its own game and recent context. Row order and seeds remain fixed.
  const outcomes = await mapConcurrent(
    jobs,
    concurrency,
    async ({ snapshot, pair, workspace }) => {
      const result = await rollout(
        policy,
        workspace,
        snapshot.board,
        snapshot.seed,
        options.moves,
        onUsage,
      );
      if (++finished[pair] === 2) onProgress?.(++pairsDone, total);
      return result;
    },
  );
  const rows: Verification["rows"] = snapshots.map(({ snapshot, split }, i) => {
    const baseline = outcomes[i * 2],
      proposed = outcomes[i * 2 + 1];
    return {
      snapshot: snapshot.id,
      split,
      seed: snapshot.seed,
      baseline: baseline.utility,
      candidate: proposed.utility,
      delta: proposed.utility - baseline.utility,
      errors: baseline.errors + proposed.errors,
      cited: proposed.cited,
    };
  });
  const mean = (split: string) => {
    const r = rows.filter((r) => r.split === split);
    return r.length ? r.reduce((s, r) => s + r.delta, 0) / r.length : 0;
  };
  const meanDelta = mean("practice"),
    regressionDelta = mean("regression");
  return {
    rows,
    meanDelta,
    regressionDelta,
    accepted: meanDelta >= 1 && regressionDelta >= -2,
    rule: verificationRule(options),
    mode: policy.mode,
    focus,
    sizes: { ...options },
  };
}
export async function examEpisode(
  policy: Policy,
  workspace: Workspace,
  seed: number,
  cap: number,
  identity: { id: string; name: string },
  arm: Arm,
  onMove?: (game: ReturnType<typeof createGame>, completed: number) => void,
): Promise<ExamRow> {
  let game = createGame(seed),
    tokens = 0,
    calls = 0,
    simulations = 0,
    invalid = 0;
  const latencyMs: number[] = [];
  let recent: RecentMove[] = [];
  let error: string | undefined;
  try {
    for (let i = 0; i < cap && !game.over && !game.won; i++) {
      const started = performance.now();
      const d = await policy.decide(
        observe(game),
        workspace,
        hash(`exam-plan:${seed}:${i}`),
        { recent },
      );
      latencyMs.push(Math.round(performance.now() - started));
      tokens += d.tokens;
      calls += d.calls;
      simulations += d.simulations;
      invalid += d.invalid ?? 0;
      const next = move(game, d.action);
      if (!next.changed) throw new Error("Illegal exam move.");
      recent = pushRecent(recent, {
        action: d.action,
        scoreDelta: next.gain,
        emptyBefore: observe(game).empty,
        emptyAfter: observe(next.game).empty,
      });
      game = next.game;
      onMove?.(game, i + 1);
      if (i % 25 === 24) await new Promise((resolve) => setTimeout(resolve, 0));
    }
  } catch (e) {
    error = e instanceof Error ? e.message : "Policy failed";
  }
  return {
    studentId: identity.id,
    name: identity.name,
    arm,
    seed,
    score: game.score,
    highest: Math.max(...game.board),
    moves: game.moves,
    reached: game.won,
    terminal: error
      ? "error"
      : game.won
        ? "target"
        : game.over
          ? "loss"
          : "cap",
    tokens,
    calls,
    simulations,
    workspaceVersion: workspace.version,
    invalid,
    latencyMs,
    error,
  };
}
const quantile = (values: number[], q: number) => {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const i = (sorted.length - 1) * q;
  const lo = Math.floor(i);
  return sorted[lo] + (sorted[Math.ceil(i)] - sorted[lo]) * (i - lo);
};
export const MILESTONES = [256, 512, 1024, 2048] as const;
// Primary outcome: mean score under the fixed cap. Everything else is supporting.
export function summarize(rows: ExamRow[], cap: number) {
  const n = rows.length;
  const success = rows.filter((r) => r.reached);
  const latencies = rows.flatMap((r) => r.latencyMs ?? []);
  return {
    n,
    meanScore: n ? rows.reduce((s, r) => s + r.score, 0) / n : 0,
    medianScore: quantile(
      rows.map((r) => r.score),
      0.5,
    ),
    milestones: Object.fromEntries(
      MILESTONES.map((m) => [
        m,
        n ? rows.filter((r) => r.highest >= m).length / n : 0,
      ]),
    ) as Record<(typeof MILESTONES)[number], number>,
    meanMoves: n ? rows.reduce((s, r) => s + r.moves, 0) / n : 0,
    losses: rows.filter((r) => r.terminal === "loss").length,
    truncated: rows.filter((r) => r.terminal === "cap").length,
    successes: success.length,
    successRate: n ? success.length / n : 0,
    successfulMeanMoves: success.length
      ? success.reduce((s, r) => s + r.moves, 0) / success.length
      : null,
    cappedMeanMoves: n
      ? rows.reduce((s, r) => s + (r.reached ? r.moves : cap), 0) / n
      : 0,
    errors: rows.filter((r) => r.terminal === "error").length,
    invalid: rows.reduce((s, r) => s + (r.invalid ?? 0), 0),
    p50Ms: quantile(latencies, 0.5),
    p95Ms: quantile(latencies, 0.95),
  };
}
const pairKey = (r: ExamRow) => `${r.repetition ?? 0}:${r.seed}:${r.studentId}`;
// Paired score difference (treatment − baseline) with a percentile bootstrap interval.
// With several training repetitions, whole repetitions are resampled (the unit of
// inference); with one, pairs are resampled and the result is exploratory.
export function pairedContrast(
  treatment: ExamRow[],
  baseline: ExamRow[],
  resamples = 4000,
) {
  const base = new Map(baseline.map((r) => [pairKey(r), r]));
  const pairs = treatment.flatMap((t) => {
    const b = base.get(pairKey(t));
    return b
      ? [
          {
            repetition: t.repetition ?? 0,
            diff: t.score - b.score,
            base: b.score,
          },
        ]
      : [];
  });
  const clusters = [...new Set(pairs.map((p) => p.repetition))].map((rep) =>
    pairs.filter((p) => p.repetition === rep),
  );
  const unit = clusters.length > 1 ? "repetition" : "pair";
  const groups = unit === "repetition" ? clusters : pairs.map((p) => [p]);
  const mean = (ps: { diff: number }[]) =>
    ps.length ? ps.reduce((s, p) => s + p.diff, 0) / ps.length : 0;
  const meanDiff = mean(pairs);
  const baselineMean = pairs.length
    ? pairs.reduce((s, p) => s + p.base, 0) / pairs.length
    : 0;
  const stats: number[] = [];
  let r = hash(`bootstrap:${pairs.length}:${meanDiff}`);
  for (let i = 0; i < resamples && groups.length; i++) {
    const sample: { diff: number }[] = [];
    for (let k = 0; k < groups.length; k++) {
      const [u, next] = draw(r);
      r = next;
      sample.push(...groups[Math.floor(u * groups.length)]);
    }
    stats.push(mean(sample));
  }
  return {
    pairs: pairs.length,
    clusters: clusters.length,
    unit,
    meanDiff,
    ci95: [quantile(stats, 0.025), quantile(stats, 0.975)] as [
      number | null,
      number | null,
    ],
    baselineMean,
    relative: baselineMean ? meanDiff / baselineMean : null,
    exploratory: clusters.length < 2,
  };
}
// Pre-registered planning target (PROTOCOL.md): ≥10% mean-score gain, interval above
// zero, and no more than 5 percentage points more error games than the baseline.
export function planningTarget(
  treatment: ExamRow[],
  baseline: ExamRow[],
  contrast: ReturnType<typeof pairedContrast>,
) {
  const errorRate = (rows: ExamRow[]) =>
    rows.length
      ? rows.filter((r) => r.terminal === "error").length / rows.length
      : 0;
  const reliability = errorRate(treatment) - errorRate(baseline) <= 0.05;
  const gain = (contrast.relative ?? 0) >= 0.1;
  const interval = (contrast.ci95[0] ?? 0) > 0;
  return {
    met: gain && interval && reliability,
    gain,
    interval,
    reliability,
    note: contrast.exploratory
      ? "One training repetition: exploratory only, regardless of this result."
      : "Repetition-level bootstrap.",
  };
}
